    out = [row[:] for row in grid]
    divider = next((r for r, row in enumerate(grid) if 2 in row), None)
    if divider is None:
        return out

    for r in range(divider):
        for c in range(w):
            if grid[r][c] == 4:
                out[r][c] = 0
                if r + 1 < divider:
                    out[r + 1][c] = 4

    # A marker two rows above the divider spreads diagonally as it approaches.
    for r in range(divider):
        for c in range(w):
            if grid[r][c] != 4 or divider - r != 2:
                continue
            if r % 2 == 0:
                for dc in (-2, 2):
                    if 0 <= c + dc < w:
                        out[r][c + dc] = 4
                for dc in (-1, 1):
                    if 0 <= c + dc < w:
                        out[r + 1][c + dc] = 4
            else:
                for dc in (-1, 1):
                    if 0 <= c + dc < w:
                        out[r][c + dc] = 4
                out[r + 1][c] = 4

    return out
